{
  "schema_version": "scientist-design-v1",
  "scenario": "two people bargaining over a mug",
  "agents": [
    {"name": "Alice", "role": "seller", "goal": "maximize profit", "constraints": ["must sell mug for at least $5"]},
    {"name": "Bob", "role": "buyer", "goal": "minimize cost", "constraints": ["willing to pay at most $7"]},
    {"name": "Charlie", "role": "observer", "goal": "assess negotiation tactics", "constraints": ["cannot intervene in negotiation"]},
    {"name": "Dana", "role": "mediator", "goal": "facilitate agreement", "constraints": ["must remain neutral"]}
  ],
  "outcome": {
    "name": "agreement price",
    "operationalization": "the final price agreed upon by Alice and Bob",
    "measurement_question": "what is the final price negotiated between the seller and buyer?",
    "respondent": "Alice and Bob"
  },
  "causes": [
    {
      "name": "initial offer",
      "hypothesis": "a higher initial offer from the seller leads to a higher agreement price",
      "predicted_direction": "increase",
      "treatment_values": ["$6", "$8", "$10"]
    },
    {
      "name": "buyer's budget",
      "hypothesis": "a lower buyer budget leads to a lower agreement price",
      "predicted_direction": "decrease",
      "treatment_values": ["$5", "$7", "$9"]
    },
    {
      "name": "mediator's presence",
      "hypothesis": "a mediator's presence leads to a more balanced agreement price",
      "predicted_direction": "non_monotonic",
      "treatment_values": ["mediator present", "mediator absent", "mediator neutral"]
    }
  ],
  "information_scope": {
    "public": ["mug's market value", "buyer's budget", "seller's minimum price"],
    "private": [
      {"agent": "Alice", "information": ["mug's true value", "previous sale prices"]},
      {"agent": "Bob", "information": ["his maximum willingness to pay", "his financial constraints"]}
    ]
  },
  "interaction": {
    "order": ["Alice", "Bob", "Dana", "Charlie"],
    "max_turns": 8,
    "stopping_rule": "agreement reached or 8 turns elapsed"
  }
}

