  "schema_version": "scientist-design-v1",
  "scenario": "A person is interviewing for a job as a lawyer",
  "agents": [
    {
      "name": "Interviewer",
      "role": "Hiring manager",
      "goal": "Assess the candidate's legal knowledge and communication skills",
      "constraints": ["Evaluate based on prepared questions", "Maintain neutrality", "Record responses"]
    },
    {
      "name": "Candidate",
      "role": "Job applicant",
      "goal": "Demonstrate legal competence and fit for the role",
      "constraints": ["Answer questions without prior knowledge of the interviewer's questions", "Respond within 30 seconds", "Speak clearly"]
    },
    {
      "name": "Note-Taker",
      "role": "Assistant",
      "goal": "Accurately record the interview for later review",
      "constraints": ["Cannot provide feedback to the interviewer", "Record only verbal responses", "Transcribe in real-time"]
    }
  ],
  "outcome": {
    "name": "Interview success",
    "operationalization": "The interviewer's assessment of the candidate's suitability for the role",
    "measurement_question": "How would the interviewer rate the candidate's performance on a scale of 1 to 10?",
    "respondent": "Interviewer"
  },
  "causes": [
    {
      "name": "Legal knowledge",
      "hypothesis": "Candidates with higher legal knowledge will perform better in the interview",
      "predicted_direction": "increase",
      "treatment_values": ["Basic legal knowledge", "Intermediate legal knowledge", "Advanced legal knowledge"]
    },
    {
      "name": "Communication clarity",
      "hypothesis": "Candidates who communicate more clearly will be rated higher",
      "predicted_direction": "increase",
      "treatment_values": ["Unclear", "Moderately clear", "Very clear"]
    },
    {
      "name": "Confidence level",
      "hypothesis": "Higher confidence leads to better interview performance",
      "predicted_direction": "increase",
      "treatment_values": ["Low confidence", "Moderate confidence", "High confidence"]
    }
  ],
  "information_scope": {
    "public": ["Interview questions", "Candidate's resume", "Job description"],
    "private": [
      {
        "agent": "Interviewer",
        "information": ["Previous interview notes", "Internal hiring criteria", "Candidate's past interviews"]
      },
      {
        "agent": "Candidate",
        "information": ["Interviewer's past interviews", "Company's legal history", "Internal hiring biases"]
      },
      {
        "agent": "Note-Taker",
        "information": ["Previous interviews", "Note-taking protocols", "Candidate's non-verbal cues"]
      }
    ]
  },
  "interaction": {
    "order": ["Interviewer", "Candidate", "Note-Taker"],
    "max_turns": 3,
    "stopping_rule": "Interview ends after the candidate answers all questions and the note-taker completes the transcription"
  }
}

