        "agent": "Agent B",
        "information": ["Market value estimates", "Investment goals"]
      },
      {
        "agent": "Agent C",
        "information": ["Collection value", "Personal interest"]
      }
    ]
  },
  "interaction": {
    "order": ["Agent A", "Agent B", "Agent C"],
    "max_turns": 3,
    "stopping_rule": "Auction ends when all agents have submitted their final bid"
  }
}

